using QtRocket::Test::checkSetterScripts;
using QtRocket::Test::listInOrder;
using QtRocket::Test::num;
using QtRocket::Test::SetterScript;

using Texts = std::vector<std::string>;

// ---- generated by scripts/make_r2_tests.py of the probe: the readers
[[nodiscard]] std::string readAxial(ApplicationSetterFixture& /*fixture*/, const RocketComponent& c)
{
    return listInOrder({asText(axialMethodName(c.getAxialMethod())), num(c.getAxialOffset()),
                        num(c.getPosition().x)});
}

