TEST(AxialPositionSetter, DoesWithEveryElementWhatOpenRocketDoes)
{
    EXPECT_EQ(checkSetterScripts(kJava), Texts{});
}

// OpenRocket sets the method and then dies of a NaN (a BugException) or stores an infinity.
TEST(AxialPositionSetter, AnOffsetThatIsNotFiniteIsNotApplied)
{
    EXPECT_EQ(checkSetterScripts(kOwn), Texts{});
}

// The cases x000, x005 and x011 of the probe, through a setter of the test's own.
TEST(AxialPositionSetter, SetsTheMethodAndThenTheOffset)
{
    const AxialPositionSetter setter;
    // The other way round the bulkhead would sit 0.1 m from the bottom of the tube, at 0.298.
    EXPECT_EQ(applyByHand(setter, ComponentKind::BULKHEAD, "method=top", "0.1", &readAxial),
              "TOP, 0.1, 0.1");
    EXPECT_EQ(applyByHand(setter, ComponentKind::BULKHEAD, "type=top", "0.1", &readAxial),
              "TOP, 0.1, 0.1");
    EXPECT_EQ(applyByHand(setter, ComponentKind::BULKHEAD, "", "0.03", &readAxial),
              "BOTTOM, 0.0, 0.198 [Invalid parameter encountered, ignoring.]");
}

/// What the setter does with a pod set that is in no tree: "set", or the message of the
/// BugError.
[[nodiscard]] std::string positionAPodSetOutsideATree()
{
    ApplicationSetterFixture  fixture;
    PodSet                    pod;
    WarningSet                warnings;
    const AxialPositionSetter setter;
    try
    {
        const Result<void> result =
            setter.set(pod, "0.1", attributesOf("method=top"), warnings, fixture.context());
        return result.has_value() ? "set" : "failed";
    }
    catch (const BugError& error)
    {
        return error.what();
    }
}

// A loader attaches a component to its parent before it sets anything (ComponentHandler), so no
// file brings this about; OpenRocket has a BugException here as well.
TEST(AxialPositionSetter, AnAssemblyOutsideATreeCannotBePositioned)
{
    EXPECT_NE(positionAPodSetOutsideATree().find("requires a parent before any positioning"),
              std::string::npos);
}

